import spdx from "./spdxIdentifiers.json";

// Generated by scripts/generate-spdx-identifiers.py from the same tables the
// NeuroContainers builder validates against (Python `packaging.licenses`).
const LICENSE_IDS = new Set(spdx.licenses.map((id) => id.toLowerCase()));
const EXCEPTION_IDS = new Set(spdx.exceptions.map((id) => id.toLowerCase()));
const OPERATORS = new Set(["and", "or", "with"]);
const LICENSE_REF = /^licenseref-[a-z0-9.-]+$/;

/**
 * Returns why `expression` is not a valid SPDX license expression, or null if
 * it is one. Mirrors `packaging.licenses.canonicalize_license_expression`:
 * identifiers and operators are case-insensitive, `+` may follow a listed
 * license, and `LicenseRef-` identifiers may use letters, digits, `.` and `-`.
 */
export function spdxExpressionError(expression: string): string | null {
    const tokens = expression
        .replace(/\(/g, " ( ")
        .replace(/\)/g, " ) ")
        .toLowerCase()
        .split(/\s+/)
        .filter(Boolean);
    const invalid = `Invalid license expression: '${expression}'`;
    let position = 0;

    const isLicenseToken = (token: string | undefined): token is string =>
        token !== undefined && !OPERATORS.has(token) && token !== "(" && token !== ")";

    // expression := term (("and" | "or") term)*
    const parseExpression = (): string | null => {
        const error = parseTerm();
        if (error) return error;
        while (tokens[position] === "and" || tokens[position] === "or") {
            position++;
            const termError = parseTerm();
            if (termError) return termError;
        }
        return null;
    };

    // term := "(" expression ")" | license ["with" exception]
    const parseTerm = (): string | null => {
        const token = tokens[position++];
        if (token === "(") {
            const error = parseExpression();
            if (error) return error;
            return tokens[position++] === ")" ? null : invalid;
        }
        if (!isLicenseToken(token)) return invalid;

        const id = token.endsWith("+") ? token.slice(0, -1) : token;
        if (id.startsWith("licenseref-")) {
            if (id !== token || !LICENSE_REF.test(id)) return `Invalid licenseref: '${token}'`;
        } else if (!LICENSE_IDS.has(id)) {
            return `Unknown license: '${id}'`;
        }

        if (tokens[position] === "with") {
            position++;
            const exception = tokens[position++];
            if (!isLicenseToken(exception)) return invalid;
            if (!EXCEPTION_IDS.has(exception)) return `Unknown license exception: '${exception}'`;
        }
        return null;
    };

    if (tokens.length === 0) return invalid;
    const error = parseExpression();
    if (error) return error;
    return position === tokens.length ? null : invalid;
}
